void VPkAddNcU64Vop3p::execute_impl(amdgpu::Wavefront &wf) {
  uint64_t exec = wf.exec();
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    const auto lhs = read_pk_u64_pair(src0, wf, lane);
    const auto rhs = read_pk_u64_pair(src1, wf, lane);
    const auto apply = [&](uint64_t lhs_value, uint64_t rhs_value, bool negate_lhs,
                           bool negate_rhs) -> uint64_t {
      using Wide = __int128;
      Wide lhs_wide = static_cast<Wide>(lhs_value);
      Wide rhs_wide = static_cast<Wide>(rhs_value);
      if (negate_lhs)
        lhs_wide = -lhs_wide;
      if (negate_rhs)
        rhs_wide = -rhs_wide;
      const Wide result = lhs_wide + rhs_wide;
      if (inst_.clamp) {
        if (result < 0)
          return 0;
        constexpr Wide kMax = static_cast<Wide>(std::numeric_limits<uint64_t>::max());
        if (result > kMax)
          return std::numeric_limits<uint64_t>::max();
      }
      return static_cast<uint64_t>(result);
    };
    const uint64_t result_lo = apply(lhs.lo, rhs.lo, (inst_.neg & 1u) != 0, (inst_.neg & 2u) != 0);
    const uint64_t result_hi =
        apply(lhs.hi, rhs.hi, (inst_.neg_hi & 1u) != 0, (inst_.neg_hi & 2u) != 0);
    write_pk_u64_pair(vdst, wf, lane, {result_lo, result_hi});
  }
}

void VPkSubNcU64Vop3p::execute_impl(amdgpu::Wavefront &wf) {
  uint64_t exec = wf.exec();
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    const auto lhs = read_pk_u64_pair(src0, wf, lane);
    const auto rhs = read_pk_u64_pair(src1, wf, lane);
    const auto apply = [&](uint64_t lhs_value, uint64_t rhs_value, bool negate_lhs,
                           bool negate_rhs) -> uint64_t {
      using Wide = __int128;
      Wide lhs_wide = static_cast<Wide>(lhs_value);
      Wide rhs_wide = static_cast<Wide>(rhs_value);
      if (negate_lhs)
        lhs_wide = -lhs_wide;
      if (negate_rhs)
        rhs_wide = -rhs_wide;
      const Wide result = lhs_wide - rhs_wide;
      if (inst_.clamp) {
        if (result < 0)
          return 0;
        constexpr Wide kMax = static_cast<Wide>(std::numeric_limits<uint64_t>::max());
        if (result > kMax)
          return std::numeric_limits<uint64_t>::max();
      }
      return static_cast<uint64_t>(result);
    };
    const uint64_t result_lo = apply(lhs.lo, rhs.lo, (inst_.neg & 1u) != 0, (inst_.neg & 2u) != 0);
    const uint64_t result_hi =
        apply(lhs.hi, rhs.hi, (inst_.neg_hi & 1u) != 0, (inst_.neg_hi & 2u) != 0);
    write_pk_u64_pair(vdst, wf, lane, {result_lo, result_hi});
  }
}

void VPkLshlAddU64Vop3p::execute_impl(amdgpu::Wavefront &wf) {
  uint64_t exec = wf.exec();
  std::array<PkU64Pair, 64> results{};
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    const auto values = read_pk_u64_pair(src0, wf, lane);
    const auto shifts = read_pk_u32_pair(src1, wf, lane);
    const auto addends = read_pk_u64_pair(src2, wf, lane);
    if (shifts.lo > 4u || shifts.hi > 4u) {
      wf.report_instruction_execution_error(
          amdgpu::InstructionExecutionError::UnsupportedOperandValue);
      return;
    }
    const uint64_t result_lo =
        amdgpu::lshl_masked(values.lo, static_cast<uint64_t>(shifts.lo)) + addends.lo;
    const uint64_t result_hi =
        amdgpu::lshl_masked(values.hi, static_cast<uint64_t>(shifts.hi)) + addends.hi;
    results[lane] = {result_lo, result_hi};
  }
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    write_pk_u64_pair(vdst, wf, lane, results[lane]);
  }
}

void VWmmaScaleF32Vop3px2::execute_impl(amdgpu::Wavefront &wf) {
  auto &cu = wf.cu();
  uint32_t vb = wf.vgpr_alloc().base;
  uint32_t dst = vb + *Isa::resolved_vgpr_offset(wf, vdst.opr_type_, vdst.encoding_value_,
                                                 vdst.vgpr_msb_role());
  uint32_t src0_base = vb + *Isa::resolved_vgpr_offset(wf, src0.opr_type_, src0.encoding_value_,
                                                       src0.vgpr_msb_role());
  uint32_t src1_base = vb + *Isa::resolved_vgpr_offset(wf, src1.opr_type_, src1.encoding_value_,
                                                       src1.vgpr_msb_role());
  uint32_t const_acc;
  auto src2_off =
      Isa::resolved_vgpr_offset(wf, src2.opr_type_, src2.encoding_value_, src2.vgpr_msb_role());
  uint32_t s2 = dst;
  if (src2_off) {
    const_acc = amdgpu::ACC_FROM_VGPR;
    s2 = vb + *src2_off;
  } else {
    const_acc = amdgpu::RegisterAccess(wf).read_scalar(src2);
  }

  const uint32_t matrix_a_fmt = inst_.opsel;
  const uint32_t matrix_b_fmt = (inst_.opsel_hi_2 << 2) | inst_.opsel_hi;
  const uint32_t matrix_a_scale =
      (scale_inst_.opsel & 0x1u) | (((scale_inst_.opsel >> 2u) & 0x1u) << 1u);
  const uint32_t matrix_b_scale =
      (scale_inst_.opsel_hi & 0x1u) | ((scale_inst_.opsel_hi_2 & 0x1u) << 1u);
  const uint32_t matrix_a_scale_fmt = scale_inst_.neg & 0x3u;
  const uint32_t matrix_b_scale_fmt = scale_inst_.neg_hi & 0x3u;
  const bool scale16 = scale_inst_.op == 0x3a;
  const bool scale0_inline_zero =
      scale_src0.encoding_value() == OpSelSrcSimple::OPR_SRC_SIMPLE_POS_INT_MIN;
  const bool scale1_inline_zero =
      scale_src1.encoding_value() == OpSelSrcSimple::OPR_SRC_SIMPLE_POS_INT_MIN;

  auto scale_word = [&](const Operand &operand, uint32_t lane) -> uint64_t {
    // Inline zero supplies a neutral E8M0 scale for every K block.
    if (operand.encoding_value() == OpSelSrcSimple::OPR_SRC_SIMPLE_POS_INT_MIN)
      return 0x7f7f7f7f7f7f7f7full;
    // Scalar scale sources use only bits 7:0, repeated for every K
    // block. VGPR scale sources retain their packed per-block bytes.
    if (operand.encoding_value() >= 0 && operand.encoding_value() <= 105) {
      const uint64_t byte = amdgpu::RegisterAccess(wf).read_lane(operand, lane) & 0xffu;
      return byte * 0x0101010101010101ull;
    }
    return scale16 ? amdgpu::RegisterAccess(wf).read_lane64(operand, lane)
                   : amdgpu::RegisterAccess(wf).read_lane(operand, lane);
  };
  auto scale0 = [&](uint32_t lane) -> uint64_t { return scale_word(scale_src0, lane); };
  auto scale1 = [&](uint32_t lane) -> uint64_t { return scale_word(scale_src1, lane); };

  bool dispatched = false;
  if (inst_.op == 0x88) {
    amdgpu::exec_wmma_f32_scaled_mixed(
        cu, 32, 16, 128, 4, 4, dst, src0_base, src1_base, s2, amdgpu::extract_fp4,
        amdgpu::extract_fp4, const_acc, scale0, scale1, matrix_a_scale, matrix_b_scale,
        scale0_inline_zero ? 0u : matrix_a_scale_fmt, scale1_inline_zero ? 0u : matrix_b_scale_fmt,
        scale16, amdgpu::wmma_c_modifier(inst_.neg, inst_.neg_hi));
    dispatched = true;
  } else {
    dispatched = amdgpu::dispatch_matrix_fmt_pair(
        matrix_a_fmt, matrix_b_fmt,
        [&](uint32_t a_bits, uint32_t b_bits, auto extract_a, auto extract_b) {
          amdgpu::exec_wmma_f32_scaled_mixed(cu, 16, 16, 128, a_bits, b_bits, dst, src0_base,
                                             src1_base, s2, extract_a, extract_b, const_acc, scale0,
                                             scale1, matrix_a_scale, matrix_b_scale,
                                             scale0_inline_zero ? 0u : matrix_a_scale_fmt,
                                             scale1_inline_zero ? 0u : matrix_b_scale_fmt, scale16,
                                             amdgpu::wmma_c_modifier(inst_.neg, inst_.neg_hi));
        });
  }
  if (!dispatched)
    throw util::UnimplementedInst(mnemonic());
}

